/** Static membership targets for the Steam Collection Rule. */
export const PERF_STEAM_COLLECTIONS = [
  { id: "perf-favorite", name: "Perf Favorites", kind: "favorite", isDynamic: false },
  { id: "perf-hidden", name: "Perf Hidden", kind: "hidden", isDynamic: false },
  { id: "perf-coop", name: "Perf Co-op", kind: "user", isDynamic: false },
  { id: "perf-indie", name: "Perf Indie", kind: "user", isDynamic: false },
  { id: "perf-long", name: "Perf Long", kind: "user", isDynamic: false },
  { id: "perf-dynamic", name: "Perf Dynamic", kind: "user", isDynamic: true },
] as const;

function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296;
  };
}

function integer(random: () => number, min: number, max: number): number {
  return min + Math.floor(random() * (max - min + 1));
}

function pick<T>(random: () => number, values: readonly T[]): T {
  return values[integer(random, 0, values.length - 1)]!;
}

function pickMany<T>(random: () => number, values: readonly T[], count: number): T[] {
  const pool = [...values];
  const chosen: T[] = [];
  for (let index = 0; index < count && pool.length > 0; index += 1) {
    const [value] = pool.splice(integer(random, 0, pool.length - 1), 1);
    chosen.push(value!);
  }
  return chosen;
}

function reviewTier(score: number): string {
  if (score >= 95) {
    return "Overwhelmingly Positive";
  }
  if (score >= 80) {
    return "Very Positive";
  }
  if (score >= 70) {
    return "Positive";
  }
  if (score >= 40) {
    return "Mixed";
  }
  if (score >= 20) {
    return "Mostly Negative";
  }
  return "Overwhelmingly Negative";
}

const LAST_PLAYED_BASE = 1_700_000_000;

/** Generate exactly the same Games for a given count and seed. */
export function generatePerfGames(count: number, seed: number, baseAppId: number): PerfGame[] {
  const random = mulberry32(seed);
  const games: PerfGame[] = [];
  for (let index = 0; index < count; index += 1) {
    const appId = baseAppId + index;
    const name = `Perf Game ${String(index + 1).padStart(5, "0")}`;
    const roll = random();
    const ownershipStatus =
      roll < 0.8 ? ("owned" as const) : roll < 0.9 ? ("local_only" as const) : ("unknown" as const);

    const installedRoll = random();
    const installed = installedRoll < 0.05 ? null : installedRoll < 0.45;

    const playtimeMinutes = integer(random, 0, 20_000);
    const lastPlayedAt =
      random() < 0.2 ? null : LAST_PLAYED_BASE - integer(random, 0, 60 * 60 * 24 * 365 * 6);
    const releaseYear = random() < 0.1 ? null : integer(random, 1995, 2025);
    const metacriticScore = random() < 0.2 ? null : integer(random, 0, 100);

    const reviewCount = random() < 0.1 ? null : integer(random, 0, 100_000);
    const reviewScore = reviewCount === null || reviewCount === 0 ? null : integer(random, 0, 100);
    const tier = reviewScore === null ? null : reviewTier(reviewScore);

    const typeRoll = random();
    const storefrontType = typeRoll < 0.05 ? null : typeRoll < 0.1 ? "dlc" : "game";
    const platforms = {
      windows: random() < 0.92,
      mac: random() < 0.35,
      linux: random() < 0.3,
    };
    if (!platforms.windows && !platforms.mac && !platforms.linux) {
      platforms.windows = true;
    }

    const tags = random() < 0.05 ? [] : pickMany(random, TAGS, integer(random, 1, 6));
    const steamCollections: string[] = [];
    if (index % 5 === 0) {
      steamCollections.push("perf-favorite");
    }
    if (index % 11 === 0) {
      steamCollections.push("perf-hidden");
    }
    if (tags.includes("Co-op") || tags.includes("Multiplayer")) {
      steamCollections.push("perf-coop");
    }
    if (tags.includes("Indie")) {
      steamCollections.push("perf-indie");
    }
    if (playtimeMinutes >= 10_000) {
      steamCollections.push("perf-long");
    }

    games.push({
      appId,
      name,
      nameKey: name.toLowerCase(),
      ownershipStatus,
      installed,
      playtimeMinutes,
      lastPlayedAt,
      releaseYear,
      metacriticScore,
      reviewScore,
      reviewTier: tier,
      reviewCount,
      storefrontType,
      platforms,
      genres: pickMany(random, GENRES, integer(random, 1, 3)),
      categories: pickMany(random, CATEGORIES, integer(random, 0, 3)),
      developers: pickMany(random, DEVELOPERS, integer(random, 1, 2)),
      publishers: pickMany(random, PUBLISHERS, integer(random, 1, 2)),
      tags,
      steamCollections,
    });
  }
  return games;
}

/** A stable manifest hash used to prove the generated fixture did not drift. */
export function fixtureChecksum(games: readonly PerfGame[]): string {
  const hash = createHash("sha256");
  for (const game of games) {
    hash.update(JSON.stringify(game));
    hash.update("\n");
  }
  return hash.digest("hex");
}

const COLLECTION_TEMPLATES: ReadonlyArray<Rule> = [
  { prefix: "AND", field: "playtime", operator: "gte", value: 600 },
  { prefix: "AND", field: "releaseYear", operator: "gte", value: 2010 },
  { prefix: "AND", field: "metacriticScore", operator: "gte", value: 75 },
  { prefix: "AND", field: "reviewCount", operator: "gte", value: 100 },
  { prefix: "AND", field: "tag", operator: "has", value: "Action" },
  { prefix: "AND", field: "genre", operator: "has", value: "RPG" },
  { prefix: "AND", field: "platform", operator: "has", value: "linux" },
  { prefix: "AND", field: "steamCollection", operator: "has", value: "perf-favorite" },
  { prefix: "OR", field: "tag", operator: "has", value: "Indie" },
  { prefix: "NOT", field: "tag", operator: "has", value: "Perf Never Matching Tag 01" },
];

/** Twenty deterministic saved Collections for the list `matchCount` budget. */
export function generatePerfSmartCollections(
  count: number,
  ruleCount = COLLECTION_TEMPLATES.length,
): PerfSmartCollection[] {
  return Array.from({ length: count }, (_, index) => {
    const rules = Array.from({ length: ruleCount }, (_, ruleIndex) => {
      const template = COLLECTION_TEMPLATES[ruleIndex % COLLECTION_TEMPLATES.length]!;
      if (template.field !== "playtime" || typeof template.value !== "number") {
        return { ...template };
      }
      return { ...template, value: template.value + index * 60 };
    });
    return {
      id: `00000000-0000-4000-8000-${String(index + 1).padStart(12, "0")}`,
      name: `Perf Collection ${String(index + 1).padStart(2, "0")}`,
      rules,
    };
  });
}

export interface SeedPerfOptions {
  games: readonly PerfGame[];
  smartCollections?: readonly PerfSmartCollection[];
  /** When false, no per-source row is seeded so every Game/source is pending. */
  withMetadataRows?: boolean;
}

const FETCHED_AT = 1_700_000_000;

/**
 * Seed a real SQLite database through the documented tables. One transaction
 * keeps the 20,000-Game fixture around a second instead of minutes.
 */
export function seedPerfLibrary(db: BetterSqlite3.Database, options: SeedPerfOptions): void {
  const withMetadataRows = options.withMetadataRows ?? true;
  db.transaction(() => {
    for (const game of options.games) {
      runSync(
        db,
        queryFor(db)
          .insertInto("games")
          .values({
            app_id: game.appId,
            name: game.name,
            name_key: game.nameKey,
            name_source: "local",
            ownership_status: game.ownershipStatus,
            installed: game.installed === null ? null : game.installed ? 1 : 0,
            playtime_minutes: game.playtimeMinutes,
            manifest_last_played_at: game.lastPlayedAt,
            source_mask: 2,
            first_seen_at: FETCHED_AT,
            last_seen_at: FETCHED_AT,
          })
          .compile(),
      );
      if (withMetadataRows) {
        runSync(
          db,
          queryFor(db)
            .insertInto("storefront_appdetails")
            .values({
              app_id: game.appId,
              type: game.storefrontType,
              developers_json: JSON.stringify(game.developers),
              publishers_json: JSON.stringify(game.publishers),
              genres_json: JSON.stringify(game.genres),
              categories_json: JSON.stringify(game.categories),
              platforms_json: JSON.stringify(game.platforms),
              release_year: game.releaseYear,
              metacritic_score: game.metacriticScore,
              store_status: game.storefrontType === null ? "missing" : "ok",
              store_fetched_at: game.storefrontType === null ? null : FETCHED_AT,
              updated_at: FETCHED_AT,
            })
            .compile(),
        );
        runSync(
          db,
          queryFor(db)
            .insertInto("steamspy_appdetails")
            .values({
              app_id: game.appId,
              tags_status: game.tags.length > 0 ? "ok" : "missing",
              tags_fetched_at: FETCHED_AT,
              updated_at: FETCHED_AT,
            })
            .compile(),
        );
      }
      for (const [tagIndex, tag] of game.tags.entries()) {
        const key = tag.toLowerCase();
        runSync(
          db,
          queryFor(db)
            .insertInto("tags")
            .values({ name: tag, name_key: key })
            .onConflict((oc) => oc.column("name_key").doNothing())
            .compile(),
        );
        const row = firstSync<{ id: number }>(
          db,
          queryFor(db).selectFrom("tags").select("id").where("name_key", "=", key).compile(),
        );
        if (row === undefined) {
          throw new Error(`Tag ${key} was not readable after insert.`);
        }
        runSync(
          db,
          queryFor(db)
            .insertInto("game_tags")
            .values({ app_id: game.appId, tag_id: row.id, votes: 1_000 - tagIndex * 10 })
            .compile(),
        );
      }
      if (withMetadataRows) {
        if (game.reviewCount === null) {
          runSync(
            db,
            queryFor(db)
              .insertInto("steam_review_summaries")
              .values({
                app_id: game.appId,
                review_status: "missing",
                updated_at: FETCHED_AT,
              })
              .compile(),
          );
        } else {
          const positive =
            game.reviewScore === null ? 0 : Math.round((game.reviewScore * game.reviewCount) / 100);
          runSync(
            db,
            queryFor(db)
              .insertInto("steam_review_summaries")
              .values({
                app_id: game.appId,
                review_positive: positive,
                review_negative: game.reviewCount - positive,
                review_total: game.reviewCount,
                review_tier: game.reviewTier,
                review_status: "ok",
                review_fetched_at: FETCHED_AT,
                updated_at: FETCHED_AT,
              })
              .compile(),
          );
        }
      }
    }

    for (const collection of PERF_STEAM_COLLECTIONS) {
      runSync(
        db,
        queryFor(db)
          .insertInto("steam_collections")
          .values({
            id: collection.id,
            name: collection.name,
            kind: collection.kind,
            is_dynamic: collection.isDynamic ? 1 : 0,
            filter_spec_json: collection.isDynamic ? '{"filter":true}' : null,
            raw_value_json: "{}",
            imported_at: FETCHED_AT,
          })
          .compile(),
      );
      if (!collection.isDynamic) {
        for (const game of options.games) {
          if (game.steamCollections.includes(collection.id)) {
            runSync(
              db,
              queryFor(db)
                .insertInto("steam_collection_games")
                .values({ steam_collection_id: collection.id, app_id: game.appId })
                .compile(),
            );
          }
        }
      }
    }

    for (const collection of options.smartCollections ?? []) {
      runSync(
        db,
        queryFor(db)
          .insertInto("smart_collections")
          .values({
            id: collection.id,
            name: collection.name,
            name_key: collection.name.toLowerCase(),
            created_at: FETCHED_AT,
            updated_at: FETCHED_AT,
          })
          .compile(),
      );
      for (const [position, rule] of collection.rules.entries()) {
        runSync(
          db,
          queryFor(db)
            .insertInto("rules")
            .values({
              smart_collection_id: collection.id,
              position,
              prefix: rule.prefix,
              field: rule.field,
              operator: rule.operator,
              value_json: JSON.stringify(rule.value),
            })
            .compile(),
        );
      }
    }

    // A completed library run gives every list a deterministic `dataAsOf`.
    if (withMetadataRows) {
      runSync(
        db,
        queryFor(db)
          .insertInto("refresh_runs")
          .values({
            scope: "library",
            mode: null,
            status: "succeeded",
            started_at: FETCHED_AT - 5,
            finished_at: FETCHED_AT,
            done: options.games.length,
          })
          .compile(),
      );
      for (const name of ["steamspy", "storefront", "steam_reviews"] as const) {
        runSync(
          db,
          queryFor(db)
            .updateTable("source_state")
            .set({ status: "ok", last_success_at: FETCHED_AT, last_attempt_at: FETCHED_AT })
            .where("name", "=", name)
            .compile(),
        );
      }
    }
  })();
}
